# test_wb_fixtures.jl — ESSF node `wb-reference-fixtures` (schedule W5-F, GLOBAL_DAG row 6).
#
# Warburton–Barack printed reference-SSF tables (arXiv:1003.1860, Tables II & III) baked as
# fixture data in test/fixtures/wb_reference.jl. This file is the drift gate:
#   (A) sha256 pin of the read-only tex mirror (test_runtime_config.jl gate-A precedent) —
#       catches drift of the mirror itself;
#   (B) EXTRACTION EQUALITY — an INDEPENDENT tex parser (below; the fixture was generated by
#       a separate one-shot script) re-greps the mirror and every fixture literal must
#       string-equal what the tex prints, cell by cell, dashes included — fixture drift vs
#       the mirror is impossible while the mirror is in the checkout;
#   (C) count + schema checks: 12 rows x 7 spin columns per table, 67 printed cells + 17
#       below-ISCO typed sentinels, printed-coverage constants [recorded decision Q2];
#   (D) physical sanity: F_r prograde/retrograde sign flip, sentinel mask == (r0 < kerr_isco(a)),
#       first printed rows straddle the ISCO (a=0 opens EXACTLY at r0 = risco = 6M), plus
#       hand-typed literal spot pins (Haas–Poisson / Diaz-Rivera anchors, tex lines 613/647);
#   (E) standalone load: the fixture is included into a fresh module — pure Base, no deps.
#
# Wiring is TEST-SIDE ONLY: fixture + this file + one runtests.jl include. No src/ change,
# no new deps (SHA is already a test-only [extras]; Spacetime is a package hard dep).

using Test
using SHA: sha256
using Spacetime: kerr_isco   # package hard dep (solid ESSF::spacetime-circular-kinematics)

# ---------------------------------------------------------------------------------------
# Independent tex re-extraction (read-only on the mirror; pure Base).
# The ONLY cell transform is the paper's exponent macro "e{-}k" -> "e-k" (macro documented
# in the Table I caption, tex line 546) plus math-mode $-stripping; significant figures
# pass through untouched. A bare "-" cell is the printed below-ISCO marker.
# ---------------------------------------------------------------------------------------

const WB_TEX_MIRROR = normpath(joinpath(@__DIR__, "..", "..", "..", "..",
    "ref-paper", "arxiv-1003.1860", "src", "Warburton.tex"))

function wb_normalize_cell(raw::AbstractString)
    s = strip(raw)
    s == "-" && return nothing
    s = strip(replace(s, "\$" => ""))
    return replace(s, "e{-}" => "e-")
end

# Extract the data rows of the WB table whose \multicolumn heading contains `marker`.
# Returns (r0_labels, cells [12 rows of 7], tex-line range of the data rows).
function wb_extract_table(texlines::Vector{String}, marker::AbstractString)
    istart = findfirst(l -> occursin(marker, l), texlines)
    istart === nothing && error("wb_extract_table: marker '$marker' not found in $WB_TEX_MIRROR")
    r0_labels = String[]
    cells = Vector{Union{Nothing, String}}[]
    firstrow, lastrow = 0, 0
    for i in istart+1:length(texlines)
        line = texlines[i]
        occursin("\\end{tabular}", line) && return (r0_labels, cells, firstrow:lastrow)
        occursin("r_0/M", line) && continue          # the column-header row
        occursin("&", line) || continue              # \hline etc.
        fields = split(replace(line, "\\\\" => ""), "&")
        length(fields) == 8 || error("wb_extract_table: $(length(fields)) fields at tex line $i")
        push!(r0_labels, replace(strip(fields[1]), "\$" => ""))
        push!(cells, [wb_normalize_cell(f) for f in fields[2:end]])
        firstrow == 0 && (firstrow = i)
        lastrow = i
    end
    error("wb_extract_table: unterminated tabular after tex line $istart")
end

@testset "wb-reference-fixtures (Warburton–Barack printed tables, W5-F)" begin
    fixture_path = joinpath(@__DIR__, "fixtures", "wb_reference.jl")
    @test isfile(fixture_path)

    # (E) standalone load: fresh module with std imports only — the fixture must need
    # NOTHING beyond Base (no package deps, no stdlib `using`).
    WB = Module(:WBReferenceStandalone)
    Base.include(WB, fixture_path)

    @testset "schema + counts" begin
        @test WB.WB_A_OVER_M == [-0.9, -0.7, -0.5, 0.0, 0.5, 0.7, 0.9]
        @test WB.WB_R0_OVER_M == [4.0, 5.0, 6.0, 7.0, 8.0, 10.0, 14.0, 20.0, 30.0, 50.0, 70.0, 100.0]
        for tbl in (WB.WB_FT, WB.WB_FR)
            @test size(tbl) == (12, 7)                            # (r0, a) as printed
            @test count(c -> c isa WB.WBRefCell, tbl) == 67       # printed cells
            @test count(c -> c === WB.WB_BELOW_ISCO, tbl) == 17   # printed '-' cells
        end
        # printed-coverage constants [recorded decision Q2]: parity domain of the PAPER
        @test WB.WB_MAX_ABS_A == maximum(abs, WB.WB_A_OVER_M) == 0.9
        @test WB.WB_MIN_PRINTED_R0 == minimum(WB.WB_R0_OVER_M) == 4.0
        # the CRP's |a|=0.998/near-ISCO comparison domain (PRIVATE WB data) is not printed:
        @test_throws ArgumentError WB.wb_cell(WB.WB_FT, 0.998, 2.0)
        @test_throws ArgumentError WB.wb_cell(WB.WB_FR, -0.998, 9.0)
        @test_throws ArgumentError WB.wb_cell(WB.WB_FR, 0.0, 9.0)
    end

    @testset "decimal-string <-> Float64 coherence" begin
        for tbl in (WB.WB_FT, WB.WB_FR), c in tbl
            c isa WB.WBRefCell || continue
            @test occursin(r"^-?\d\.\d+e-\d+$", c.dec)   # normalized scientific form only
            @test c.value == parse(Float64, c.dec)       # Float64 derived from the string
            @test isfinite(c.value) && c.value != 0.0
        end
    end

    @testset "below-ISCO sentinel pattern" begin
        # exact printed mask — identical in BOTH tables (captions, tex lines 589/642)
        below = Dict(4.0 => [-0.9, -0.7, -0.5, 0.0, 0.5],
                     5.0 => [-0.9, -0.7, -0.5, 0.0],
                     6.0 => [-0.9, -0.7, -0.5],
                     7.0 => [-0.9, -0.7, -0.5],
                     8.0 => [-0.9, -0.7])
        @test sum(length, values(below)) == 17
        for tbl in (WB.WB_FT, WB.WB_FR)
            for (i, r0) in enumerate(WB.WB_R0_OVER_M), (j, a) in enumerate(WB.WB_A_OVER_M)
                sentinel = tbl[i, j] === WB.WB_BELOW_ISCO
                @test sentinel == (a in get(below, r0, Float64[]))
                # physics: dash <=> orbit below the Kerr ISCO radius (M = 1)
                @test sentinel == (r0 < kerr_isco(a))
            end
        end
    end

    @testset "physical sanity: signs, ISCO edge, spot pins" begin
        # F_t (dissipative, energy loss) is positive everywhere printed
        @test all(c -> !(c isa WB.WBRefCell) || c.value > 0, WB.WB_FT)
        # F_r sign flip retrograde -> prograde (paper Sec. about r_c: repulsive for a <= 0
        # at all printed radii; attractive at every printed prograde cell since r_c(a) < 5
        # for a >= 0.5M)
        for (j, a) in enumerate(WB.WB_A_OVER_M), i in 1:12
            c = WB.WB_FR[i, j]
            c isa WB.WBRefCell || continue
            @test (a <= 0 ? c.value > 0 : c.value < 0)
        end
        # first printed row of each column sits at/above the ISCO; the row below it (when
        # one is printed) is a sentinel — "ISCO rows present at the printed radii"
        for (a, r0_first) in ((-0.9, 10.0), (-0.7, 10.0), (-0.5, 8.0), (0.0, 6.0),
                              (0.5, 5.0), (0.7, 4.0), (0.9, 4.0))
            @test WB.wb_cell(WB.WB_FT, a, r0_first) isa WB.WBRefCell
            @test WB.wb_cell(WB.WB_FR, a, r0_first) isa WB.WBRefCell
            @test r0_first >= kerr_isco(a)      # a = 0 opens EXACTLY at the ISCO (r0 = 6M)
            i = findfirst(==(r0_first), WB.WB_R0_OVER_M)
            if i > 1
                r0_below = WB.WB_R0_OVER_M[i-1]
                @test WB.wb_cell(WB.WB_FT, a, r0_below) === WB.WB_BELOW_ISCO
                @test WB.wb_cell(WB.WB_FR, a, r0_below) === WB.WB_BELOW_ISCO
            end
        end
        @test kerr_isco(0.0) == 6.0
        # hand-typed literal spot pins (typed straight from the printed tables — independent
        # of BOTH the fixture generator and the parser above)
        @test WB.wb_cell(WB.WB_FT, 0.0, 6.0).dec == "3.60907254e-4"   # Haas–Poisson anchor (tex l.613)
        @test WB.wb_cell(WB.WB_FR, 0.0, 6.0).dec == "1.677283e-4"     # Diaz-Rivera anchor (tex l.647)
        @test WB.wb_cell(WB.WB_FT, -0.9, 10.0).dec == "4.60475173e-5"
        @test WB.wb_cell(WB.WB_FT, 0.9, 4.0).dec == "1.14204820e-3"
        @test WB.wb_cell(WB.WB_FR, 0.9, 4.0).dec == "-9.5941e-4"
        @test WB.wb_cell(WB.WB_FR, 0.5, 5.0).dec == "-4.160235e-5"
        @test WB.wb_cell(WB.WB_FR, -0.9, 100.0).dec == "1.1508e-9"
        @test WB.wb_cell(WB.WB_FT, 0.9, 100.0).value == 3.32002917e-9
    end

    if isfile(WB_TEX_MIRROR)
        @testset "extraction equality vs read-only tex mirror" begin
            # (A) mirror pin — any tex drift forces a fixture review + hash re-record
            @test bytes2hex(sha256(read(WB_TEX_MIRROR))) == WB.WB_TEX_SHA256
            texlines = readlines(WB_TEX_MIRROR)
            for (marker, expected_lines, tbl) in (
                    ("(M^2/q^2)F_t", WB.WB_FT_TEX_DATA_LINES, WB.WB_FT),
                    ("(M^2/q^2)F_r", WB.WB_FR_TEX_DATA_LINES, WB.WB_FR))
                r0_labels, cells, rows = wb_extract_table(texlines, marker)
                @test rows == expected_lines             # data-row line range as recorded
                @test length(r0_labels) == 12
                @test parse.(Float64, r0_labels) == WB.WB_R0_OVER_M
                for i in 1:12, j in 1:7
                    tex = cells[i][j]
                    if tex === nothing
                        @test tbl[i, j] === WB.WB_BELOW_ISCO
                    else
                        @test tbl[i, j] isa WB.WBRefCell
                        @test tbl[i, j].dec == tex       # STRING equality: sig figs exact
                    end
                end
            end
        end
    else
        @warn "WB tex mirror absent — extraction-equality re-grep skipped " *
              "(fixture still pinned by its baked literals + spot pins)" WB_TEX_MIRROR
    end
end
